    data_column_sidecar: Arc<DataColumnSidecar<P>>,
    state: Option<Arc<BeaconState<P>>>,
    block_seen: bool,
    origin: &DataColumnSidecarOrigin,
    metrics: Option<&Arc<Metrics>>,
) -> Result<DataColumnSidecarAction<P>> {

